import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { overdueInvoices } from '../src/reports.js';

test('overdueInvoices returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2024-02-01');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no overdue invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const issued = issueInvoice(r.value, []);
  assert.equal(issued.ok, true);

  // Invoice due date is 2024-02-14 (NET30 default)
  // Report date is 2024-02-14, so not overdue
  const result = overdueInvoices([issued.value], '2024-02-14');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes invoice when dueDate is before asOf', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const issued = issueInvoice(r.value, []);
  assert.equal(issued.ok, true);

  // Invoice due date is 2024-02-14, report date is 2024-02-15
  const result = overdueInvoices([issued.value], '2024-02-15');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.value.number);
});

test('overdueInvoices includes required fields', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const issued = issueInvoice(r.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2024-02-20');
  assert.equal(result.length, 1);

  const inv = result[0];
  assert.equal(typeof inv.number, 'string');
  assert.equal(inv.customerId, 'C-001');
  assert.equal(inv.dueDate, '2024-02-14');
  assert.equal(typeof inv.daysOverdue, 'number');
  assert(inv.daysOverdue > 0);
  assert.equal(typeof inv.due, 'number');
  assert(inv.due > 0);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const issued = issueInvoice(r.value, []);
  assert.equal(issued.ok, true);

  // Invoice due date is 2024-02-14
  // Report date is 2024-02-24 (10 days later)
  const result = overdueInvoices([issued.value], '2024-02-24');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 10);
});

test('overdueInvoices excludes draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  // Keep as draft, don't issue

  const result = overdueInvoices([r.value], '2024-02-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const issued = issueInvoice(r.value, []);
  assert.equal(issued.ok, true);

  const paid = recordPayment(issued.value, { amount: 114950, date: '2024-01-20' });
  assert.equal(paid.ok, true);
  assert.equal(paid.value.status, 'paid');

  const result = overdueInvoices([paid.value], '2024-02-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const issued = issueInvoice(r.value, []);
  assert.equal(issued.ok, true);

  const partial = recordPayment(issued.value, { amount: 50000, date: '2024-01-20' });
  assert.equal(partial.ok, true);
  assert.equal(partial.value.status, 'partially_paid');

  const result = overdueInvoices([partial.value], '2024-02-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, 64950); // 114950 - 50000
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  assert.equal(r1.ok, true);

  const issued1 = issueInvoice(r1.value, []);
  assert.equal(issued1.ok, true);
  // Due date: 2024-01-31

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-20',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  assert.equal(r2.ok, true);

  const issued2 = issueInvoice(r2.value, ['INV-2024-0001']);
  assert.equal(issued2.ok, true);
  // Due date: 2024-02-19

  const r3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-01-10',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  assert.equal(r3.ok, true);

  const issued3 = issueInvoice(r3.value, ['INV-2024-0001', 'INV-2024-0002']);
  assert.equal(issued3.ok, true);
  // Due date: 2024-02-09

  // Report date is 2024-03-01
  const result = overdueInvoices([issued1.value, issued2.value, issued3.value], '2024-03-01');
  assert.equal(result.length, 3);
  assert.equal(result[0].daysOverdue, 41); // 2024-01-31 to 2024-03-01
  assert.equal(result[1].daysOverdue, 11); // 2024-02-09 to 2024-03-01
  assert.equal(result[2].daysOverdue, 11); // 2024-02-19 to 2024-03-01
  // The last two have the same daysOverdue, so their relative order depends on stability
  // We just verify the first is most overdue
});

